import functools

def log(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"appel de {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

@log
def saluer(nom):
    return f"Bonjour {nom}"

