def log(f):
    def wrapper(*a):
        print("avant")
        r = f(*a)
        print("après")
        return r
    return wrapper

@log
def carre(x):
    print("calcul")
    return x * x

print(carre(3))

def chrono(f):
    def wrapper(*args, **kwargs):
        debut = time.perf_counter()
        f(*args, **kwargs)
        print(time.perf_counter() - debut)
    return wrapper

@chrono
def somme(a, b):
    return a + b

