from functools import lru_cache
appels = 0

@lru_cache
def fib(n):
    global appels
    appels += 1
    return n if n < 2 else fib(n - 1) + fib(n - 2)

fib(30)
print(appels)

compteur = 0

def travail():
    global compteur
    for _ in range(100_000):
        compteur += 1

for t in [Thread(target=travail) for _ in range(4)]:
    t.start()

def compter(f):
    def wrapper(*args):
        wrapper.appels += 1
        return f(*args)
    wrapper.appels = 0
    return wrapper

@compter
def ident(x):
    return x

ident(1)
ident(2)
print(ident.appels)

